-- Ana Luiza (CA-CID-AT-FAM-2026-001) — preservação do histórico do contrato
-- vindo do banco antigo congelado (zsxpdbhdvbuulwpepemd) + complemento de cadastro.
-- Autorização: Proprietária, 20/10/2026 ("aprovo as correções somente em relação a Ana Luiza").
--
-- O QUE FAZ
-- 1) Cria public.contract_history_imports (somente leitura para admin/operações,
--    imutável: sem policy de insert/update/delete para usuários).
-- 2) Guarda, como histórico (NÃO como versão ativa), o que só existia no banco antigo
--    para o contrato a11a0000-0000-4000-8000-0000000000c1:
--      6 contract_versions (v1..v6, 21/08 a 10/09; v5 = v6, 14 cláusulas, selo RASCUNHO INTERNO),
--      84 contract_validation_results, 20 contract_review_events.
-- 3) Corrige o cadastro do caso (telefone, nascimento e quadra/lote de Ana; quadra/lote de Adair e Alice),
--    só quando o valor atual for o lido na B1 de 21/10/2026.
--
-- O QUE NÃO FAZ
-- - Não cria/ativa/substitui versão de contrato, não altera status, valor, cláusula ou assinatura.
-- - Só sobrescreve o telefone de Ana (C1), e apenas se ainda for o valor errado lido na B1. Demais campos: só se vazios.
-- - Não apaga nada. Idempotente (on conflict do nothing / where ... is null).

create table if not exists public.contract_history_imports (
  id uuid primary key,
  organization_id uuid not null,
  contract_id uuid not null,
  source_project text not null,
  source_table text not null,
  source_created_at timestamptz,
  payload jsonb not null,
  imported_at timestamptz not null default now(),
  import_note text
);
alter table public.contract_history_imports enable row level security;
alter table public.contract_history_imports force row level security;
drop policy if exists "chi_select_admin_ops" on public.contract_history_imports;
create policy "chi_select_admin_ops" on public.contract_history_imports for select to authenticated
  using (public.is_org_member(organization_id)
         and (public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'operacoes')));
create index if not exists contract_history_imports_contract_idx on public.contract_history_imports(contract_id);

