insert into public.contract_history_imports(id, organization_id, contract_id, source_project, source_table, source_created_at, payload, import_note)
select (e->>'id')::uuid, (e->>'organization_id')::uuid, (e->>'contract_id')::uuid,
       'zsxpdbhdvbuulwpepemd', t.tbl, (e->>'created_at')::timestamptz, e,
       'Histórico do banco antigo congelado em 20/10/2026. Não é versão vigente.'
from src,
 lateral (values ('contract_versions', j->'versions'), ('contract_validation_results', j->'validations'), ('contract_review_events', j->'reviews')) t(tbl, arr),
 lateral jsonb_array_elements(t.arr) e
on conflict (id) do nothing;

